"""Finalize only this review's output inventory. Parent observes this command's raw exit."""
from pathlib import Path
import json,hashlib,datetime,subprocess,sys
O=Path(__file__).resolve().parent
assert not (O/'output-manifest.json').exists() and not (O/'receipt.json').exists()
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
files={str(p.relative_to(O)):{'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(O.rglob('*')) if p.is_file()}
manifest={'schema':'guard_review_output_manifest_v1','files':files,'count':len(files),'excludes':['output-manifest.json','receipt.json'],'no_candidate_artifacts_in_owned_output':True}
mp=O/'output-manifest.json';mp.write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
p=subprocess.run([sys.executable,'-B','-m','json.tool',str(mp)],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True);assert p.returncode==0
state=json.loads((O/'inputs/state.json').read_text());start=state['tasks']['postovernight_long_D2_guard_review_r1']['registered_at_utc'];finish=datetime.datetime.now(datetime.timezone.utc)
elapsed=(finish-datetime.datetime.fromisoformat(start)).total_seconds();assert elapsed<=900
commands=[{'receipt':p.name,**json.loads(p.read_text())} for p in sorted(O.glob('command-*.json'))]
receipt={'schema':'frozen_guard_review_completion_v1','review_complete':True,'candidate_accepted_for_training':False,'verdict':'rejected','known_confirmed_findings':2,'new_confirmed_findings':1,'new_finding_id':'TIMING-FAILURE-SUPPRESSES-RECEIPT','new_finding_severity':'P2_reporting','output_manifest':'output-manifest.json','output_manifest_sha256':sha(mp),'output_manifest_entries':len(files),'output_manifest_json_tool_raw_exit':p.returncode,'review_registration_utc':start,'finished_utc':finish.isoformat(),'review_elapsed_seconds_upper_bound_UTC':elapsed,'budget_seconds':900,'timing_scope':'UTC registration-to-finalization upper bound; no cross-interpreter monotonic subtraction','source_hashes':json.loads((O/'verification.json').read_text())['sha256'],'scoped_preservation_check':'preservation-postcheck.json','input_hashes':'input-hashes-final.json','findings':'findings.json','audit':'audit.md','counts_not_added':{'retained_final_unit_methods':87,'retained_OS_lifecycle_executions':62,'retained_latch_subprocesses_nested_in_one_unit_method':6,'retained_stress_attempts':1,'historical_R4_controls_transferred':0,'review_suite_or_matrix_or_stress_reruns':0},'review_command_records':len(commands),'commands_with_nonzero_exit':[{'receipt':c['receipt'],'exit_code':c['exit_code'],'command':c['command']} for c in commands if c['exit_code']!=0],'finalizer_invocation':{'argv':[sys.executable,'-B',str(Path(__file__).resolve())],'raw_exit_authority':'external calling tool; this receipt does not self-certify finalizer raw exit'},'review_fixture_corrections_retained':True,'candidate_source_or_capsule_state_docs_protocol_writes':False,'parent_mutable_bookkeeping_not_frozen':True,'ML_native_inference_training_or_checkpoint_deserialization':False,'provider_calls_delegation_lease_scheduler_commits_PR_deploy_external_messages':False}
rp=O/'receipt.json';rp.write_text(json.dumps(receipt,indent=2,sort_keys=True)+'\n')
q=subprocess.run([sys.executable,'-B','-m','json.tool',str(rp)],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,text=True);assert q.returncode==0
print(json.dumps({'review_complete':True,'candidate_accepted_for_training':False,'new_findings':1,'known_confirmed_findings':2,'manifest_entries':len(files),'manifest_sha256':sha(mp),'receipt_sha256':sha(rp),'elapsed_UTC_upper_bound':elapsed,'output_manifest_and_receipt_json_tool_raw_exits':[p.returncode,q.returncode]}))
